// src/theme/catalog.ts
var parsedThemeCache = new Map;
function listBuiltinThemeNames() {
  return [...BUILTIN_THEME_NAMES];
}
function isBuiltinThemeName(name) {
  return Object.prototype.hasOwnProperty.call(BUILTIN_THEME_SOURCES, name);
}
function getBuiltinThemeSource(name) {
  if (!isBuiltinThemeName(name))
    return null;
  return BUILTIN_THEME_SOURCES[name];
}
function getBuiltinTheme(name) {
  if (!isBuiltinThemeName(name))
    return null;
  const cached = parsedThemeCache.get(name);
  if (cached)
    return cached;
  const parsed = parseGhosttyTheme(BUILTIN_THEME_SOURCES[name]);
  if (!parsed.name)
    parsed.name = name;
  parsedThemeCache.set(name, parsed);
  return parsed;
}
