    selectionState,
    linkState,
    scrollbarState,
    imeState,
    updateCanvasCursor,
    updateLinkHover,
    positionToCell: positionToCell2,
    positionToPixel,
    clearSelection: clearSelection2,
    updateImePosition: updateImePosition2,
