            const constraint = nerdConstraint ?? (colorGlyph ? DEFAULT_EMOJI_CONSTRAINT2 : defaultConstraint);
            const constraintWidth = Math.max(1, item.constraintWidth ?? Math.round(maxWidth / cellW));
