      stage.uniformData[5] = stage.params[1] ?? 0;
      stage.uniformData[6] = stage.params[2] ?? 0;
      stage.uniformData[7] = stage.params[3] ?? 0;
      stage.uniformData[8] = stage.params[4] ?? 0;
